class Solution {
public:
    long long countPairs(vector<int>& nums1, vector<int>& nums2) {
        vector<long long> diff;
        for (int i = 0; i < (int)nums1.size(); ++i) {
            diff.push_back((long long)nums1[i] - nums2[i]);
        }
        sort(diff.begin(), diff.end());
        int l = 0, r = (int)diff.size() - 1;
        long long answer = 0;
        while (l < r) {
            if (diff[l] + diff[r] > 0) {
                answer += r - l;
                --r;
            } else {
                ++l;
            }
        }
        return answer;
    }
};
